class Solution:
    def findMinimumTime(self, strength: List[int], k: int) -> int:
        n = len(strength)
        FULL = (1 << n) - 1
        INF = float('inf')
        dp = [INF] * (1 << n)
        dp[0] = 0
        for mask in range(FULL):
            if dp[mask] == INF:
                continue
            x = 1 + k * bin(mask).count('1')
            for i in range(n):
                if not mask >> i & 1:
                    t = (strength[i] + x - 1) // x
                    nm = mask | 1 << i
                    dp[nm] = min(dp[nm], dp[mask] + t)
        return dp[FULL]

