class Solution {
public:
    int findMinimumTime(vector<int>& strength, int k) {
        int n = strength.size(), FULL = (1 << n) - 1;
        vector<long long> dp(1 << n, LLONG_MAX / 2);
        dp[0] = 0;
        for (int mask = 0; mask < FULL; mask++) {
            if (dp[mask] >= LLONG_MAX / 2) continue;
            long long x = 1 + (long long)k * __builtin_popcount(mask);
            for (int i = 0; i < n; i++) {
                if (!(mask >> i & 1)) {
                    long long t = (strength[i] + x - 1) / x;
                    int nm = mask | 1 << i;
                    dp[nm] = min(dp[nm], dp[mask] + t);
                }
            }
        }
        return (int)dp[FULL];
    }
};

