class Solution:
    def findMinimumTime(self, strength: List[int], k: int) -> int:
        from functools import lru_cache
        n = len(strength)
        FULL = (1 << n) - 1
        @lru_cache(maxsize=None)
        def dfs(mask):
            if mask == FULL:
                return 0
            x = 1 + k * bin(mask).count('1')
            return min((strength[i] + x - 1) // x + dfs(mask | 1 << i)
                       for i in range(n) if not mask >> i & 1)
        return dfs(0)

