class Solution {
    vector<int> s_; int k_, n_, full_;
    vector<long long> memo_;
    long long dfs(int mask) {
        if (mask == full_) return 0;
        long long& r = memo_[mask];
        if (r != -1) return r;
        long long x = 1 + (long long)k_ * __builtin_popcount(mask);
        r = LLONG_MAX / 2;
        for (int i = 0; i < n_; i++)
            if (!(mask >> i & 1))
                r = min(r, (s_[i] + x - 1) / x + dfs(mask | 1 << i));
        return r;
    }
public:
    int findMinimumTime(vector<int>& strength, int k) {
        s_ = strength; k_ = k; n_ = strength.size(); full_ = (1 << n_) - 1;
        memo_.assign(1 << n_, -1);
        return (int)dfs(0);
    }
};

