class Solution {
    private int[] s; private int k, n, full;
    private long[] memo;
    private long dfs(int mask) {
        if (mask == full) return 0;
        if (memo[mask] != -1) return memo[mask];
        long x = 1 + (long) k * Integer.bitCount(mask);
        long best = Long.MAX_VALUE / 2;
        for (int i = 0; i < n; i++)
            if ((mask >> i & 1) == 0)
                best = Math.min(best, (s[i] + x - 1) / x + dfs(mask | 1 << i));
            return memo[mask] = best;
    }
    public int findMinimumTime(int[] strength, int k) {
        s = strength; this.k = k; n = strength.length; full = (1 << n) - 1;
        memo = new long[1 << n]; Arrays.fill(memo, -1);
        return (int) dfs(0);
    }
}

