var findMinimumTime = function(strength, k) {
    const n = strength.length, FULL = (1 << n) - 1;
    const memo = new Array(1 << n).fill(-1);
    const bc = x => { let c = 0; while (x) { x &= x - 1; c++; } return c; };
    const dfs = mask => {
        if (mask === FULL) return 0;
        if (memo[mask] !== -1) return memo[mask];
        const x = 1 + k * bc(mask);
        let best = Infinity;
        for (let i = 0; i < n; i++)
            if (!(mask >> i & 1))
                best = Math.min(best, Math.ceil(strength[i] / x) + dfs(mask | 1 << i));
        return memo[mask] = best;
    };
    return dfs(0);
};
